#!/usr/bin/env sh
set -eu

BASE=d8d7e08643923537386b9a1386debec8b0202a8e
BRANCH=work/ux-polish-20260911

git fetch --prune origin work/rule-ux-polish-stage1-20260911 >/dev/null
test "$(git rev-parse origin/work/rule-ux-polish-stage1-20260911)" = "$BASE"
git checkout -B "$BRANCH" "$BASE" >/dev/null
test -z "$(git status --porcelain)"

python3 - <<'PY'
from pathlib import Path

p = Path('apps/mobile/src/screens/hardware-setup/pages/SensorSetupPage.tsx')
s = p.read_text()

def once(old: str, new: str, label: str):
    global s
    n = s.count(old)
    if n != 1:
        raise SystemExit(f'{label}: expected 1 match, got {n}')
    s = s.replace(old, new, 1)

once("import { DiagnosticRow, Modal, ToastViewport } from '@lcl/ui';", "import { Modal, ToastViewport } from '@lcl/ui';", 'ui import')
once("import { IconSettings } from '@tabler/icons-react';", "import { IconClock, IconPencil, IconTrash } from '@tabler/icons-react';", 'icons import')
once("""  | { kind: 'ble' }\n  | { kind: 'settings'; deviceId: string }\n  | { kind: 'remove'; device: SensorDraftDevice };""", """  | { kind: 'ble' }\n  | { kind: 'remove'; device: SensorDraftDevice };""", 'dialog union')
once("""  const [dialog, setDialog] = useState<SensorDialogState>({ kind: 'none' });\n  const [didSubmitSensorAdd, setDidSubmitSensorAdd] = useState(false);""", """  const [dialog, setDialog] = useState<SensorDialogState>({ kind: 'none' });\n  const [editingSensorId, setEditingSensorId] = useState<string | null>(null);\n  const [didSubmitSensorAdd, setDidSubmitSensorAdd] = useState(false);""", 'editing state')
once("""  const sensorSettingsId = dialog.kind === 'settings' ? dialog.deviceId : null;\n  const sensorPendingRemoval = dialog.kind === 'remove' ? dialog.device : null;""", """  const sensorPendingRemoval = dialog.kind === 'remove' ? dialog.device : null;""", 'settings id')
once("""  const sensorSettingsDevice =\n    flow.sensorDevices.find((device) => device.id === sensorSettingsId) ?? null;\n  const sensorDeviceCount = flow.sensorDevices.length;""", """  const sensorDeviceCount = flow.sensorDevices.length;""", 'settings device')
once("""  const openSensorSettings = (device: SensorDraftDevice) => {\n    setDialog({ kind: 'settings', deviceId: device.id });\n  };\n\n  const openRemoveFromSettings = (device: SensorDraftDevice) => {\n    setDialog({ kind: 'remove', device });\n  };\n\n""", "", 'settings handlers')

start = s.find("      <Modal\n        closeLabel={t('common.close')}\n        open={sensorSettingsDevice !== null}")
end = s.find("      <Modal\n        closeLabel={t('common.cancel')}", start)
if start == -1 or end == -1:
    raise SystemExit('settings modal boundaries not found')
s = s[:start] + s[end:]

old_card = """          return (\n            <article key={device.id} className=\"saved-list__item sensor-saved-card\">\n              <div className=\"sensor-card-header\">\n                <h3 className=\"sensor-card-title\">{device.name}</h3>\n                <button\n                  className=\"icon-action saved-list__settings-toggle\"\n                  type=\"button\"\n                  aria-label={t('hardware.sensor.settingsAria', {\n                    name: device.name\n                  })}\n                  title={t('hardware.sensor.settingsTitle')}\n                  onClick={() => openSensorSettings(device)}\n                >\n                  <IconSettings className=\"icon-action__svg\" aria-hidden=\"true\" />\n                </button>\n              </div>\n              <div className=\"sensor-metric-grid\">\n                <div\n                  className={\n                    hasTemperatureData\n                      ? 'sensor-data-metric-card'\n                      : 'sensor-data-metric-card sensor-data-metric-card--empty'\n                  }\n                >\n                  <span className=\"sensor-data-metric-card__label\">\n                    {t('hardware.metrics.temperature')}\n                  </span>\n                  <strong\n                    className={\n                      hasTemperatureData\n                        ? 'sensor-data-metric-card__value'\n                        : 'sensor-data-metric-card__value sensor-data-metric-card__value--empty'\n                    }\n                  >\n                    {formatNullableMetric(\n                      temperatureSample?.temperatureC,\n                      '°C',\n                      1,\n                      t('common.missingData')\n                    )}\n                  </strong>\n                </div>\n                <div\n                  className={\n                    hasHumidityData\n                      ? 'sensor-data-metric-card'\n                      : 'sensor-data-metric-card sensor-data-metric-card--empty'\n                  }\n                >\n                  <span className=\"sensor-data-metric-card__label\">\n                    {t('hardware.metrics.humidity')}\n                  </span>\n                  <strong\n                    className={\n                      hasHumidityData\n                        ? 'sensor-data-metric-card__value'\n                        : 'sensor-data-metric-card__value sensor-data-metric-card__value--empty'\n                    }\n                  >\n                    {formatNullableMetric(\n                      humiditySample?.humidityPct,\n                      '%',\n                      1,\n                      t('common.missingData')\n                    )}\n                  </strong>\n                </div>\n              </div>\n            </article>\n          );"""

new_card = """          const latest = latestSample(samples);\n          const batterySample = latestBatterySample(samples);\n          const rssiSample = latestNumericSample(samples, 'rssi');\n          const isEditing = editingSensorId === device.id;\n\n          return (\n            <article key={device.id} className=\"saved-list__item sensor-saved-card\">\n              <div className=\"sensor-card-header\">\n                {isEditing ? (\n                  <input\n                    autoFocus\n                    className=\"sensor-card-name-input\"\n                    aria-label={t('hardware.sensor.nameLabel')}\n                    type=\"text\"\n                    value={device.name}\n                    onBlur={() => setEditingSensorId(null)}\n                    onChange={(event) =>\n                      flow.setSensorDeviceName(device.id, event.currentTarget.value)\n                    }\n                    onKeyDown={(event) => {\n                      if (event.key === 'Enter' || event.key === 'Escape') {\n                        event.currentTarget.blur();\n                      }\n                    }}\n                  />\n                ) : (\n                  <div className=\"sensor-card-title-row\">\n                    <h3 className=\"sensor-card-title\">{device.name}</h3>\n                    <button\n                      className=\"icon-action rule-summary-icon-action\"\n                      type=\"button\"\n                      aria-label={t('hardware.sensor.nameLabel')}\n                      title={t('hardware.sensor.nameLabel')}\n                      onClick={() => setEditingSensorId(device.id)}\n                    >\n                      <IconPencil className=\"icon-action__svg\" aria-hidden=\"true\" />\n                    </button>\n                  </div>\n                )}\n                <div className=\"sensor-card-actions\">\n                  {device.profileId === 'xiaomi_lywsd03mmc_bthome_v2' && (\n                    <button\n                      className=\"icon-action\"\n                      type=\"button\"\n                      disabled={flow.setPvvxTimeMutation.isPending}\n                      aria-label={t('hardware.sensor.pvvxSetTimeTitle')}\n                      title={t('hardware.sensor.pvvxSetTimeTitle')}\n                      onClick={() => flow.setPvvxTimeMutation.mutate(device)}\n                    >\n                      <IconClock className=\"icon-action__svg\" aria-hidden=\"true\" />\n                    </button>\n                  )}\n                  <button\n                    className=\"icon-action icon-action--danger\"\n                    type=\"button\"\n                    aria-label={t('hardware.sensor.deleteTitle')}\n                    title={t('hardware.sensor.deleteTitle')}\n                    onClick={() => setDialog({ kind: 'remove', device })}\n                  >\n                    <IconTrash className=\"icon-action__svg\" aria-hidden=\"true\" />\n                  </button>\n                </div>\n              </div>\n              <div className=\"sensor-metric-grid\">\n                <div\n                  className={\n                    hasTemperatureData\n                      ? 'sensor-data-metric-card'\n                      : 'sensor-data-metric-card sensor-data-metric-card--empty'\n                  }\n                >\n                  <span className=\"sensor-data-metric-card__label\">\n                    {t('hardware.metrics.temperature')}\n                  </span>\n                  <strong\n                    className={\n                      hasTemperatureData\n                        ? 'sensor-data-metric-card__value'\n                        : 'sensor-data-metric-card__value sensor-data-metric-card__value--empty'\n                    }\n                  >\n                    {formatNullableMetric(\n                      temperatureSample?.temperatureC,\n                      '°C',\n                      1,\n                      t('common.missingData')\n                    )}\n                  </strong>\n                </div>\n                <div\n                  className={\n                    hasHumidityData\n                      ? 'sensor-data-metric-card'\n                      : 'sensor-data-metric-card sensor-data-metric-card--empty'\n                  }\n                >\n                  <span className=\"sensor-data-metric-card__label\">\n                    {t('hardware.metrics.humidity')}\n                  </span>\n                  <strong\n                    className={\n                      hasHumidityData\n                        ? 'sensor-data-metric-card__value'\n                        : 'sensor-data-metric-card__value sensor-data-metric-card__value--empty'\n                    }\n                  >\n                    {formatNullableMetric(\n                      humiditySample?.humidityPct,\n                      '%',\n                      1,\n                      t('common.missingData')\n                    )}\n                  </strong>\n                </div>\n              </div>\n              <dl className=\"sensor-card-details\">\n                <div>\n                  <dt>{t('hardware.sensor.typeLabel')}</dt>\n                  <dd>{sensorProfileDisplayLabels[device.profileId]}</dd>\n                </div>\n                <div>\n                  <dt>{t('hardware.metrics.battery')}</dt>\n                  <dd>{formatBattery(batterySample, t('common.missingData'))}</dd>\n                </div>\n                <div>\n                  <dt>{t('common.rssi')}</dt>\n                  <dd>\n                    {formatNullableMetric(\n                      rssiSample?.rssi,\n                      ' dBm',\n                      0,\n                      t('common.missingData')\n                    )}\n                  </dd>\n                </div>\n                <div>\n                  <dt>{t('hardware.metrics.lastMeasurement')}</dt>\n                  <dd>{formatSeenAt(latest, locale, t('common.missingData'))}</dd>\n                </div>\n                <div className=\"sensor-card-details__wide\">\n                  <dt>MAC</dt>\n                  <dd>{device.runtimeAddress}</dd>\n                </div>\n              </dl>\n            </article>\n          );"""

if old_card not in s:
    raise SystemExit('saved sensor card block not found')
s = s.replace(old_card, new_card, 1)
p.write_text(s)

cssp = Path('apps/mobile/src/theme/theme.css')
css = cssp.read_text()
css += """\n\n/* Compact saved-device cards: UX polish 2026-09-11 */\n.sensor-saved-card {\n  gap: var(--lcl-spacing-sm);\n  padding: var(--lcl-spacing-md);\n}\n\n.sensor-card-header {\n  align-items: center;\n  display: grid;\n  gap: var(--lcl-spacing-sm);\n  grid-template-columns: minmax(0, 1fr) auto;\n}\n\n.sensor-card-title-row,\n.sensor-card-actions {\n  align-items: center;\n  display: flex;\n  gap: var(--lcl-spacing-xs);\n  min-width: 0;\n}\n\n.sensor-card-title-row h3 {\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n\n.sensor-card-name-input {\n  min-height: var(--lcl-size-compact-control-min-height);\n  min-width: 0;\n  width: 100%;\n}\n\n.sensor-card-details {\n  display: grid;\n  gap: var(--lcl-spacing-xs) var(--lcl-spacing-md);\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  margin: 0;\n}\n\n.sensor-card-details > div {\n  align-items: baseline;\n  display: flex;\n  gap: var(--lcl-spacing-xs);\n  justify-content: space-between;\n  min-width: 0;\n}\n\n.sensor-card-details dt {\n  color: var(--lcl-color-text-muted);\n  font-size: var(--lcl-font-size-sm);\n}\n\n.sensor-card-details dd {\n  font-size: var(--lcl-font-size-sm);\n  font-weight: var(--lcl-font-weight-bold);\n  margin: 0;\n  min-width: 0;\n  overflow-wrap: anywhere;\n  text-align: right;\n}\n\n.sensor-card-details__wide {\n  grid-column: 1 / -1;\n}\n"""
cssp.write_text(css)
PY

pnpm exec prettier --write \
  apps/mobile/src/screens/hardware-setup/pages/SensorSetupPage.tsx \
  apps/mobile/src/theme/theme.css
pnpm exec eslint apps/mobile/src/screens/hardware-setup/pages/SensorSetupPage.tsx
pnpm quality:ux
pnpm --filter @lcl/mobile typecheck
set +e
pnpm --filter @lcl/mobile test -- hardware-setup.test.tsx
TEST_EXIT=$?
set -e

echo SENSOR_STAGE2_DRAFT_TEST_EXIT=$TEST_EXIT
git diff --check
git status --short
exit $TEST_EXIT
